//MESH_BEGIN
u: 0, pi/2, 40
v: -1, 1, 40
//MESH_END

// Calabi-Yau: sezione 2D della quintica di Fermat, grado n scelto dallo slider.
//   z1^n + z2^n = 1,  con z1,z2 complessi
// Per ogni coppia di radici n-esime dell'unita' (k1,k2) c'e' una patch:
//   z1 = e^(2 pi i k1/n) * (cos w)^(2/n)
//   z2 = e^(2 pi i k2/n) * (sin w)^(2/n)     con w = u + i v
// Con n = 5 e' la figura canonica delle illustrazioni sulla teoria delle stringhe.
//
// GRADO INTERO: una patch per mesh, n*n in tutto, dal campo Meshes del pannello
// Multi Mesh (floor(A+0.5)^2): cambiando il grado nascono esattamente le patch
// che servono. Gli indici si calcolano sulla griglia viva (k1 = mesh % n,
// k2 = mesh / n).
//
// VERSIONE 3D: la quarta dimensione e' proiettata QUI dentro, mescolata nella
// z dall'angolo B (0.785 = pi/4 e' l'inquadratura canonica). La componente w
// del vec4 resta 0, quindi la figura non dipende dalle rotazioni 4D.

A := int(2,5);          // grado della quintica: slider a scatti interi

float n  = clamp(floor(A + 0.5), 2.0, 5.0);
// NUMERAZIONE COMPATTA: la patch `mesh` porta la coppia (k1, k2) = (mesh % n, mesh / n).
float k1 = mod(float(mesh), n);
float k2 = floor(float(mesh) / n);
float p  = 2.0 / n;

// w = u + i v;  cos(w) e sin(w) complessi
vec2 cw = vec2( cos(u) * cosh(v), -sin(u) * sinh(v));
vec2 sw = vec2( sin(u) * cosh(v),  cos(u) * sinh(v));

// Potenza complessa in forma polare. Sul dominio dichiarato Re(cos w) e
// Re(sin w) restano POSITIVE: l'argomento sta in (-pi/2, pi/2), lontano dal
// salto di atan, quindi niente taglio di ramo ne' cuciture fra patch.
float rc = safePow(length(cw), p);
float tc = p * atan(cw.y, cw.x);
float rs = safePow(length(sw), p);
float ts = p * atan(sw.y, sw.x);

// Radici n-esime dell'unita': e^(2 pi i k/n)
float a1 = 2.0 * pi * k1 / n;
float a2 = 2.0 * pi * k2 / n;

vec2 z1 = rc * vec2(cos(tc + a1), sin(tc + a1));
vec2 z2 = rs * vec2(cos(ts + a2), sin(ts + a2));

// R^4 -> R^3: le due parti reali, le immaginarie mescolate dall'angolo B
return vec4(z1.x,
            z2.x,
            cos(B) * z1.y + sin(B) * z2.y,
            0.0);
